package com.rationportal.controller; import com.rationportal.repository.RationCardRepository; import com.rationportal.repository.FamilyMemberRepository; import com.rationportal.repository.DistributionLogRepository; import com.rationportal.repository.RationCardApplicationRepository; import com.rationportal.repository.GrievanceRepository; import org.springframework.web.bind.annotation.*; import java.util.LinkedHashMap; import java.util.Map; @RestController @RequestMapping("/api/transparency") public class TransparencyController { private final RationCardRepository rationCardRepository; private final FamilyMemberRepository familyMemberRepository; private final DistributionLogRepository distributionLogRepository; private final RationCardApplicationRepository applicationRepository; private final GrievanceRepository grievanceRepository; public TransparencyController(RationCardRepository r, FamilyMemberRepository f, DistributionLogRepository d, RationCardApplicationRepository a, GrievanceRepository g){this.rationCardRepository=r;this.familyMemberRepository=f;this.distributionLogRepository=d;this.applicationRepository=a;this.grievanceRepository=g;} @GetMapping("/summary") public Map<String,Object> summary(){Map<String,Object> result=new LinkedHashMap<>();result.put("totalRationCards",rationCardRepository.count());result.put("totalFamilyMembers",familyMemberRepository.count());result.put("totalDistributionRecords",distributionLogRepository.count());result.put("totalApplications",applicationRepository.count());result.put("totalGrievances",grievanceRepository.count());return result;} }
